import os
import subprocess
import sys

SCENARIOS = r'''
import click
from click.testing import CliRunner


@click.group(context_settings={"help_option_names": ["-h", "--help"]})
def cli():
    pass


@cli.command()
@click.option("-h", "--host", required=True)
@click.option("--port", type=int)
def serve(host, port):
    click.echo(f"{host}:{port}")


@cli.command()
@click.option("--port", type=int)
def status(port):
    click.echo(f"status {port}")


@click.command(context_settings={"help_option_names": ["-h", "--usage", "--help"]})
@click.option("-h", "--host")
@click.option("--port", type=int)
def three(host, port):
    pass


@click.command(context_settings={"help_option_names": ["-h"]})
@click.option("-h", "--host")
@click.option("--port", type=int)
def solo(host, port):
    pass


@click.group(context_settings={"help_option_names": ["-h", "--help"]})
@click.option("-h", "--host")
def app(host):
    pass


@app.command()
@click.option("--port", type=int)
def sub(port):
    click.echo(f"sub {port}")


runner = CliRunner()


def error_lines(cmd, args):
    result = runner.invoke(cmd, args)
    assert result.exit_code == 2, (args, result.exit_code, result.output)
    return result.output.splitlines()


def hints(out):
    return [line for line in out if line.startswith("Try ")]


# The shadowed -h must not be offered; --help is the next configured name.
for args in (["serve", "--port", "x", "-h", "a"], ["serve"]):
    out = error_lines(cli, args)
    assert hints(out) == ["Try 'cli serve --help' for help."], out
result = runner.invoke(cli, ["serve", "--help"])
assert result.exit_code == 0 and "Usage: cli serve" in result.output, result.output

# First configured name that still works, in configured order.
out = error_lines(three, ["--port", "x"])
assert hints(out) == ["Try 'three --usage' for help."], out

# Nothing shadowed: hint unchanged (first configured name).
out = error_lines(cli, ["status", "--port", "x"])
assert hints(out) == ["Try 'cli status -h' for help."], out
out = error_lines(cli, ["nope"])
assert hints(out) == ["Try 'cli -h' for help."], out

# A group's own -h/--host shadows -h for the group's errors, but not for its
# subcommand, where -h is still the help option (hint unchanged there).
out = error_lines(app, ["nope"])
assert hints(out) == ["Try 'app --help' for help."], out
out = error_lines(app, ["sub", "--port", "x"])
assert hints(out) == ["Try 'app sub -h' for help."], out
result = runner.invoke(app, ["sub", "-h"])
assert result.exit_code == 0 and "Usage: app sub" in result.output, result.output

# No help option left at all: the error is shown without any hint.
out = error_lines(solo, ["--port", "x"])
assert hints(out) == [], out
assert any(line.startswith("Error:") for line in out), out
'''

# Help option names are kept in sets internally; run under fixed hash seeds so
# any dependence on set iteration order is caught deterministically.
for seed in range(6):
    proc = subprocess.run(
        [sys.executable, "-c", SCENARIOS],
        env=dict(os.environ, PYTHONHASHSEED=str(seed)),
        capture_output=True,
        text=True,
        timeout=60,
    )
    assert proc.returncode == 0, (seed, proc.stdout, proc.stderr)

