def to_header(self) -> str:
    """Convert the stored values into a cache control header. Field names
    given to ``no-cache`` and ``private`` always use the quoted-string form
    required by RFC 9111.
    """
    return ", ".join(
        f"{key}={http.quote_header_value(value, allow_token=False)}"
        if value is not None and key in {"no-cache", "private"}
        else http.dump_header({key: value})
        for key, value in self.items()
    )
